def isTrue(c: CFormula)(implicit ta: TypeAnalyzer): Boolean = implies(True, c)

def isTrue(e: EFormula)(implicit ta: TypeAnalyzer): Boolean = implies(True, e)

private def removeDups[T](s: Set[T], eq: (T, T)=> Boolean) = 
  s.foldLeft(Set[T]()){(ns, i) =>
    if(ns.exists(eq(i, _)))
      ns
    else
      ns ++ Set(i)
  }

private def maximalCFormulas(s: Set[CFormula])(implicit ta: TypeAnalyzer) = {
  val nds = removeDups(s, (a: CFormula, b: CFormula) => equivalent(a, b))
  nds.filterNot{c => nds.exists(d => implies(c, d) && !equivalent(c,d))}
}

/* A conjunction or a disjunction is reduced once in each analyzer: asked again, the
 * analyzer answers with its first reduction (TypeAnalyzer.reduced). */
def reduce(c: CFormula)(implicit ta: TypeAnalyzer): CFormula = c match {
  case _: And | _: Or => ta.reduced(c)(reduceOnce(c))
  case _ => c
}

private def reduceOnce(c: CFormula)(implicit ta: TypeAnalyzer): CFormula =  c match {
  case And(ts, os, ns) =>
    def tSimplify(ip: (_InferenceVarType, TPrimitive)): Option[(_InferenceVarType, TPrimitive)] = ip match {
      // catch trivial contradictions 
      case (i, TPrimitive(pl,nl,pu,nu,pe,ne)) 
        if (nl.contains(i) || nu.contains(i) || pe.contains(i) || 
            nl.contains(BOTTOM)|| ne.contains(BOTTOM) || nu.contains(ANY)) =>
          None
      case (i, TPrimitive(pl,nl,pu,nu,pe,ne))
        if (pe.contains(ANY)) =>
          tSimplify(i, TPrimitive(pl, nl, Set(BOTTOM), nu, Set(), ne))
      case (i, TPrimitive(pl,nl,pu,nu,pe,ne)) =>
        Some((i, TPrimitive(maxTypes(pl.filter(_!=i)), minTypes(nl) ++ nl.filter(_==ANY), 
                                    minTypes(pu.filter(_!=i)) , maxTypes(nu) ++ nu.filter(_==BOTTOM), 
                                    maxTypes(pe), minTypes(ne) ++ ne.filter(_==ANY))))
    }
    // Comprises means there are more of these
    def tContradiction(ip: (_InferenceVarType, TPrimitive)) = {
      val TPrimitive(pl,nl,pu,nu,pe,ne) = ip._2
      if(isFalse(ta.subtype(ta.join(pl), ta.meet(pu))) ||
         nl.exists(n => pl.exists(ta.lteq(n, _))) ||
         nu.exists(n => pu.exists(ta.lteq(_, n))) ||
         pe.exists(e => pu.exists(ta.lteq(_,e))) ||
         pl.exists(l => pe.exists(e => isFalse(ta.excludes(l,e)))) ||
         ne.exists(n => pe.exists(ta.lteq(n, _))) ||
         ne.exists(n => pu.exists(ta.definitelyExcludes(n, _))))
        None
      else
        Some(ip)
    }
    def tRedundant(ip: (_InferenceVarType, TPrimitive)) = {
      val TPrimitive(pl,nl,pu,nu,pe,ne) = ip._2
      Some((ip._1, TPrimitive(pl,
                     nl.filterNot(n => pu.exists(p => isFalse(ta.subtype(n, p)))).
                        filterNot(n => pe.exists(ta.definitelyExcludes(n, _))),
                     pu,
                     nu.filterNot(n => pl.exists(p => isFalse(ta.subtype(p, n)))).
                        filterNot(n => pe.exists(ta.definitelyExcludes(n, _))),
                     pe.filterNot(p => pu.exists(ta.definitelyExcludes(p, _))),
                     ne.filterNot(n => pu.exists(ta.lteq(_, n))).
                        filterNot(n => pl.exists(p => isFalse(ta.excludes(p, n)))))))
    }
    def tTrivial(ip: (_InferenceVarType, TPrimitive)) = {
      val TPrimitive(pl,nl,pu,nu,pe,ne) = ip._2
      pl.isEmpty && nl.isEmpty && pu.isEmpty && nu.isEmpty && pe.isEmpty && ne.isEmpty
    }
    def oSimplify(ip: (_InferenceVarOp, OPrimitive)) = {
      val (i, OPrimitive(ps, ns)) = ip
      val sps = removeDups(ps - i, oEq)
      val sns = removeDups(ns, oEq)
      (i, OPrimitive(sps, sns))
    }
    def oContradiction(ip: (_InferenceVarOp, OPrimitive)) = {
      val (i, OPrimitive(ps, ns)) = ip
      if(ns.contains(i) || ps.exists(p => ns.contains(p)) || ps.filterNot(_.isInstanceOf[_InferenceVarOp]).size > 1)
        None
      else
        Some(ip)
    }
    def oTrivial(ip: (_InferenceVarOp, OPrimitive)) = {
      val (i, OPrimitive(ps, ns)) = ip
      ps.isEmpty && ns.isEmpty
    }
    def nSimplify(ip: (_InferenceVarInt, NPrimitive)) = {
      val (i, NPrimitive(ps, ns)) = ip
      (i, NPrimitive(removeDups(ps.filterNot(nEq(i, _)), nEq), removeDups(ns, nEq)))
    }
    // A size variable equal to two different sizes, or to arithmetic, has no solution
    def nContradiction(ip: (_InferenceVarInt, NPrimitive)) = {
      val (i, NPrimitive(ps, ns)) = ip
      if(ns.exists(nEq(i, _)) || ps.exists(p => ns.exists(nEq(p, _))) ||
         ps.exists(p => !isNatTerm(p) && !p.isInstanceOf[_InferenceVarInt]) ||
         removeDups(ps.filterNot(_.isInstanceOf[_InferenceVarInt]), nEq).size > 1)
        None
      else
        Some(ip)
    }
    def nTrivial(ip: (_InferenceVarInt, NPrimitive)) = {
      val (i, NPrimitive(ps, ns)) = ip
      ps.isEmpty && ns.isEmpty
    }
    val nts = ts.map(tSimplify).map(_.flatMap(tContradiction)).map(_.flatMap(tRedundant)).map(_.getOrElse(return False)).filterNot(tTrivial)
    val nos = os.map(oSimplify).map(oContradiction).map(_.getOrElse(return False)).filterNot(oTrivial)
    val nns = ns.map(nSimplify).map(nContradiction).map(_.getOrElse(return False)).filterNot(nTrivial)
    if (nts.isEmpty && nos.isEmpty && nns.isEmpty)
      return True
    else
      And(Map(nts.toSeq: _*), Map(nos.toSeq: _*), Map(nns.toSeq: _*)) 
  case Or(cs) =>
    val rcs = cs.map(reduce(_))
    if(rcs.contains(True))
      True
    else {
      val ncs = maximalCFormulas(rcs)
      ncs.size match {
        case 0 => False
        case 1 => ncs.head
        case _ => Or(ncs.asInstanceOf[Set[And]])
      }
    }
  case _ => c
}

private def minTypes(s: Set[Type])(implicit ta: TypeAnalyzer) =
    TU.conjuncts(ta.meet(s))

private def maxTypes(s: Set[Type])(implicit ta: TypeAnalyzer) =
    TU.disjuncts(ta.join(s))

def reduce(e: EFormula)(implicit ta: TypeAnalyzer): EFormula = e match {
  case Conjuncts(as, os, ms) => 
    val ras = reduce(as, ta.equiv).map{x => removeDups(x, (a: Type, b: Type) => ta.equiv(a, b))}.
      filter{_.size > 1}
    val ros = reduce(os, (a: Op, b: Op) => a==b).map{
      x => removeDups(x, (a: Op, b: Op) => a==b)}.
      filter{_.size > 1}

class TypeAnalyzer(val traits: TraitTable, val env: KindEnv) extends BoundedLattice[Type]{

  private final val debugSubtype = ProjectProperties.getBoolean("fortress.debug.analyzer.subtype", false)
  private final val cacheSubtypes = ProjectProperties.getBoolean("fortress.analyzer.subtype.cache", true)
  private final val cacheExcludes = ProjectProperties.getBoolean("fortress.analyzer.excludes.cache", true)
  private final val cacheNormalizeTrait = ProjectProperties.getBoolean("fortress.analyzer.normalize.trait.cache", true)
  private final val cacheNormalizeVar = ProjectProperties.getBoolean("fortress.analyzer.normalize.var.cache", true)
  private final val cacheNormalizeTuple = ProjectProperties.getBoolean("fortress.analyzer.normalize.tuple.cache", true)
  private final val cacheNormalizeArrow = ProjectProperties.getBoolean("fortress.analyzer.normalize.arrow.cache", true)
  private final val cacheNormalizeOther = ProjectProperties.getBoolean("fortress.analyzer.normalize.Other.cache", true)

  type hType = (Boolean, Boolean, Type, Type)
  implicit val ta: TypeAnalyzer = this

  def top = ANY
  def bottom = BOTTOM

  def lteq(x: Type, y: Type): Boolean =  isTrue(subtype(x, y))
  def meet(x: Type, y: Type): Type = meet(List(x, y))
  def meet(x: Iterable[Type]): Type = normalize(makeIntersectionType(x))
  def join(x: Type, y: Type): Type = join(List(x, y))
  def join(x: Iterable[Type]): Type = normalize(makeUnionType(x))

  protected def pMeet(x: Type, y: Type)(implicit history: Set[hType]): Type = pNorm(makeIntersectionType(List(x, y)))

  def subtype(x: Type, y: Type): CFormula =
    sub(normalize(x), normalize(y))(Set())

  protected def sub(x: Type, y: Type)(implicit history: Set[hType]): CFormula = 
    pSub(x, y)(false, history)

  def notSubtype(x: Type, y: Type): CFormula = 
    nsub(normalize(x), normalize(y))(Set())

  protected def nsub(x: Type, y: Type)(implicit history: Set[hType]): CFormula = 
    pSub(x, y)(true, history)

  private val pSubMemo = new scala.collection.mutable.HashMap[(Type, Type, Boolean, Set[hType]), CFormula]()

  private var pSubDepthForPrinting: Int = 0
  private final val indentationPadding = "   |   |   |   |   |   |   |   |   |   |"

  protected def pSub(x: Type, y: Type)(implicit negate: Boolean, history: Set[hType]): CFormula = {
     val savedDepthForPrinting = pSubDepthForPrinting
     val indentation = indentationPadding.take(savedDepthForPrinting % indentationPadding.size)
     if (debugSubtype) {
//         System.err.println(indentation + "psub > (" + x.getClass + "!" + x + ", " + y.getClass + "!" + y + ", " + negate + "), history=" + history)
//         System.err.println(indentation + "psub > (" + x.getClass + "!" + x + ", " + y.getClass + "!" + y + ", " + negate + "), env=" + env)
         System.err.println(indentation + "psub > (" + x + ", " + y + ", " + negate + "), env=" + env)
         pSubDepthForPrinting += 1
	 if (pSubDepthForPrinting > 50) bug(x, "pSub stack getting too big!")
     }
     val rval = if (x == y)
           pTrue()
         else if (cacheSubtypes && !opensSizes(x))
           traits.groundAnswer(true, x, y, negate) match {
            case null => pSubMemo.get((x, y, negate, history)) match {
              case Some(v) => traits.readContext(); v
              case _ =>
                val before = traits.contextReads
                val result = pSubInner(x,y)
                pSubMemo += ((x, y, negate, history) -> result)
                traits.ground(true, x, y, negate, before, result)
                result
            }
            case v => v
           }
         else pSubInner(x,y)
     if (debugSubtype) {
         System.err.println(indentation + "psub < (" + x + ", " + y + ", " + negate + ") RETURNS " + rval)
         pSubDepthForPrinting = savedDepthForPrinting
     }
     rval
  }

  protected def pSubInner(x: Type, y: Type)(implicit negate: Boolean, history: Set[hType]): CFormula = (x, y) match {
    case (a, b) if nDiffer(a, b) => pFalse()
    case _ => False
  }

  def excludes(x: Type, y: Type): CFormula =
    exc(normalize(removeSelf(x)), normalize(removeSelf(y)))(Set())

  protected def exc(x: Type, y: Type)(implicit history: Set[hType]): CFormula = 
    pExc(x,y)(false, history)

  def definitelyExcludes(x: Type, y: Type): Boolean =
    isTrue(excludes(x,y))

  // dExc's answers in this analyzer, by the question with its inference variables renamed apart:
  // an answer is the same under every renaming of them, so a question asked again with fresh
  // variables, as each inference makes them, is computed once. An answer is kept only from an empty
  // cycle history, marked if its computation read the context, so that a hit on it is a read of the
  // context too, and shared through the trait table if it read none; a computation that opened a
  // size is not kept.
  private final val cacheExclusions = ProjectProperties.getBoolean("fortress.analyzer.exclusion.cache", true)
  private val exclusionMemo = new scala.collection.mutable.HashMap[(Type, Type), (Boolean, Boolean)]()

  def dExc(x: Type, y: Type)(implicit history: Set[hType]): Boolean =
    if (!cacheExclusions || !history.isEmpty) isTrue(exc(x,y))
    else TypeAnalyzer.renamedApart(x, y) match {
      case None => isTrue(exc(x,y))
      case Some(question) => exclusionMemo.get(question) match {
        case Some((v, contextual)) => if (contextual) traits.readContext(); v
        case None => traits.sharedExclusion(question) match {
          case null =>
            val before = traits.contextReads
            val opened = openedSizeCount
            val result = isTrue(exc(x,y))
            if (openedSizeCount == opened) {
              val contextual = traits.contextReads != before
              exclusionMemo += (question -> (result, contextual))
              if (!contextual) traits.shareExclusion(question, result)
            }
            result
          case shared =>
            exclusionMemo += (question -> (shared.booleanValue, false))
            shared.booleanValue
        }
      }
    }

  /*
   * Given two types x and y this method computes the constraints
   * under which x and y do not exclude one another. For example if
   * we have x=List[\$i\] and y=List[\$k\] then x and y exclude one another
   * unless $i=$j. Note that this method only generates equality constraints.
   */
  def notExcludes(x: Type , y: Type): CFormula = nExc(normalize(x), normalize(y))(Set())

  protected def nExc(x: Type, y: Type)(implicit history: Set[hType]): CFormula = 
    pExc(x,y)(true, history)

  /** Determine if a collection of types all exclude each other. */
  def allExclude(ts: Iterable[Type]): CFormula =
    and(Pairs.distinctPairsFrom(ts).map(tt => excludes(tt._1, tt._2)))

  def anyExclude(ts: Iterable[Type]):CFormula =
    or(Pairs.distinctPairsFrom(ts).map(tt => excludes(tt._1, tt._2)))


  private val pExcMemo = new scala.collection.mutable.HashMap[(Type, Type, Boolean, Set[hType]), CFormula]()

  protected def pExc(x: Type, y: Type)(implicit negate: Boolean, history: Set[hType]): CFormula = {
    if (x == y) pFalse()
    else if (cacheExcludes)
      traits.groundAnswer(false, x, y, negate) match {
        case null => pExcMemo.get((x, y, negate, history)) match {
          case Some(v) => traits.readContext(); v
          case _ =>
            val before = traits.contextReads
            val result = pExcInner(x,y)
            pExcMemo += ((x, y, negate, history) -> result)
            traits.ground(false, x, y, negate, before, result)
            result
        }
        case v => v
      }
    else pExcInner(x,y)
  }

  protected def pExcInner(x: Type, y: Type)(implicit negate: Boolean, history: Set[hType]): CFormula = (removeSelf(x), removeSelf(y)) match {

package com.sun.fortress.scala_src.typechecker

import _root_.junit.framework._
import _root_.junit.framework.Assert._
import com.sun.fortress.nodes._
import com.sun.fortress.nodes_util.NodeFactory._
import com.sun.fortress.scala_src.nodes._
import com.sun.fortress.scala_src.typechecker.Formula._
import com.sun.fortress.scala_src.types.TypeAnalyzer
import com.sun.fortress.scala_src.useful.TypeParser

/* A reduction asked again in one analyzer is answered with its first answer, and never with another analyzer's. */
class ReductionMemoJUTest extends TestCase {

  def typeAnalyzer(str: String) = TypeParser.parse(TypeParser.typeAnalyzer, str).get
  def typ(str: String) = TypeParser.parse(TypeParser.typ, str).get
  def nTyp(str: String) = TypeParser.parse(TypeParser.namedType, str).get

  /** An analyzer that counts the meets it is asked. */
  class CountingAnalyzer(ta: TypeAnalyzer) extends TypeAnalyzer(ta.traits, ta.env) {
    var meets = 0
    override def meet(x: Iterable[Type]): Type = { meets += 1; super.meet(x) }
  }

  /** i between lower and upper. */
  def between(i: _InferenceVarType, lower: Type, upper: Type): CFormula =
    And(Map(i -> TPrimitive(Set(lower), Set(), Set(upper), Set(), Set(), Set())), Map())

  /** The type parameter T bounded by the given type. */
  def tBoundedBy(bound: String): StaticParam = {
    val t = nTyp("T")
    SStaticParam(t.getInfo, 0, t.getName, List(nTyp(bound).asInstanceOf[BaseType]), Nil, None, false, SKindType(), false)
  }

  def testReductionAskedAgainIsTheFirstAnswer() = {
    val ta = new CountingAnalyzer(typeAnalyzer("{trait Aa, trait Bb extends {Aa}}"))
    val c = between(make_InferenceVarType(typeSpan), typ("Bb"), typ("Aa"))
    val first = reduce(c)(ta)
    assertTrue("the reduction leaves a constraint: " + first, first.isInstanceOf[And])
    val meetsOnce = ta.meets
    assertTrue("the first reduction meets the upper bounds", meetsOnce > 0)
    val second = reduce(c)(ta)
    assertTrue("the second reduction is the first's answer", second eq first)
    assertEquals("the second reduction asks no meet", meetsOnce, ta.meets)
  }

  def testReductionOverTypeVariableIsEachAnalyzersOwn() = {
    val base = typeAnalyzer("{trait Aa, trait Cc, trait Dd}")
    val i = make_InferenceVarType(typeSpan)
    // T at or below i, and i below Cc: satisfiable where T extends Cc, a contradiction where T extends Dd
    val c = between(i, typ("T"), typ("Cc"))
    for (order <- List(List("Cc", "Dd"), List("Dd", "Cc"))) {
      val analyzers = order.map(b => (b, base.extend(List(tBoundedBy(b)), None)))
      for ((b, ta) <- analyzers ++ analyzers) {
        val r = reduce(c)(ta)
        if (b == "Cc") assertTrue("T extends Cc: " + r, r.isInstanceOf[And])
        else assertEquals("T extends Dd", False, r)
      }
    }
  }

  def testReductionOverTypeVariableReadsTheContextEachTime() = {
    val ta = typeAnalyzer("{trait Aa, trait Cc}").extend(List(tBoundedBy("Cc")), None)
    val c = between(make_InferenceVarType(typeSpan), typ("T"), typ("Cc"))
    val reads0 = ta.traits.contextReads
    reduce(c)(ta)
    val reads1 = ta.traits.contextReads
    assertTrue("the reduction reads T's bound", reads1 > reads0)
    reduce(c)(ta)
    assertTrue("the reduction asked again counts as a read of the context", ta.traits.contextReads > reads1)
  }
}
