import java.lang.classfile.*;
import java.lang.classfile.attribute.CodeAttribute;
import java.nio.file.*;
import java.util.*;
import java.util.stream.*;
public class Scan {
    public static void main(String[] a) throws Exception {
        Path root = Paths.get(a[0]);
        int limit = Integer.parseInt(a[1]);
        List<Path> files;
        try (Stream<Path> s = Files.walk(root)) { files = s.filter(p -> p.toString().endsWith(".class")).sorted().collect(Collectors.toList()); }
        int n = 0;
        for (Path p : files) {
            ClassModel m = ClassFile.of().parse(Files.readAllBytes(p));
            for (MethodModel mm : m.methods()) {
                Optional<CodeAttribute> c = mm.findAttribute(Attributes.code());
                if (c.isPresent() && c.get().codeLength() > limit)
                    System.out.println(c.get().codeLength() + "\t" + m.thisClass().asInternalName() + "." + mm.methodName().stringValue() + mm.methodType().stringValue());
            }
            n++;
        }
        System.err.println("classes scanned: " + n);
    }
}
